<?php if(!defined('ABSPATH'))exit; $configured=SEO_Manager_Instant_Indexing::configured(); $used=SEO_Manager_Instant_Indexing::quota_used(); $limit=(int)seom_get('indexing_daily_limit',200); $logs=SEO_Manager_Instant_Indexing::get_logs(100); $sa=SEO_Manager_Instant_Indexing::service_account(); ?>
<div class="seom-panel seom-google-hero"><div><span class="seom-eyebrow">GOOGLE INDEXING API</span><h2>Instant Indexing</h2><p>Notify Google when eligible URLs are added, updated or removed. Google currently limits its Indexing API to pages that contain <code>JobPosting</code> or <code>BroadcastEvent</code> in <code>VideoObject</code>. This plugin uses a service account and keeps strict mode enabled by default.</p></div><div><span class="seom-google-status <?php echo $configured?'connected':''; ?>"><?php echo $configured?'Configured':'Not configured'; ?></span></div></div>
<?php if(isset($_GET['status'])): ?><div class="notice notice-<?php echo $_GET['status']==='error'?'error':'success'; ?>"><p><?php echo esc_html($_GET['message']??ucfirst((string)$_GET['status'])); ?></p></div><?php endif; ?>
<?php if(isset($_GET['uploaded'])):?><div class="notice notice-success"><p>Google service account JSON saved securely.</p></div><?php endif; ?>
<div class="seom-two">
<div class="seom-panel"><h3>1. Google service account</h3><p>Create a service account in Google Cloud, enable the Indexing API, download its JSON key, then add the service account email as an appropriate user/owner for the verified Search Console property.</p><?php if($configured): ?><p><strong>Service account:</strong> <?php echo esc_html($sa['client_email']??'Configured'); ?></p><p><strong>Project:</strong> <?php echo esc_html($sa['project_id']??''); ?></p><?php endif; ?><form method="post" enctype="multipart/form-data" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="seom_indexing_upload"><?php wp_nonce_field('seom_indexing_upload'); ?><input type="file" name="indexing_service_json" accept="application/json,.json" required><p><button class="button button-primary">Upload Service Account JSON</button></p></form></div>
<div class="seom-panel"><h3>2. Automatic submission</h3><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="seom_indexing_save"><?php wp_nonce_field('seom_indexing_save'); ?><label class="seom-toggle-row inline"><span><strong>Enable Instant Indexing</strong><small>Enable manual and automatic Google notifications.</small></span><input type="checkbox" name="indexing_enabled" value="1" <?php checked((int)seom_get('indexing_enabled',0),1); ?>></label><label class="seom-toggle-row inline"><span><strong>Auto-submit published/updated URLs</strong><small>Runs after a post becomes publishable.</small></span><input type="checkbox" name="indexing_auto_publish" value="1" <?php checked((int)seom_get('indexing_auto_publish',1),1); ?>></label><label class="seom-toggle-row inline"><span><strong>Auto-submit deleted URLs</strong><small>Sends URL_DELETED when supported content moves to Trash.</small></span><input type="checkbox" name="indexing_auto_delete" value="1" <?php checked((int)seom_get('indexing_auto_delete',1),1); ?>></label><label class="seom-toggle-row inline"><span><strong>Strict Google eligibility mode</strong><small>Only submit URLs whose content exposes JobPosting or BroadcastEvent structured data.</small></span><input type="checkbox" name="indexing_strict_mode" value="1" <?php checked((int)seom_get('indexing_strict_mode',1),1); ?>></label><label>Configured daily submission budget<input type="number" min="1" max="10000" name="indexing_daily_limit" value="<?php echo esc_attr($limit); ?>"><small>This is a local safety budget, not Google's guaranteed quota.</small></label><p><button class="button button-primary">Save Instant Indexing Settings</button></p></form></div></div>
<div class="seom-cards"><div class="seom-card"><span>Requests in last 24h</span><strong><?php echo (int)$used; ?></strong></div><div class="seom-card"><span>Local safety budget</span><strong><?php echo (int)$limit; ?></strong></div><div class="seom-card"><span>Remaining</span><strong><?php echo max(0,$limit-$used); ?></strong></div><div class="seom-card"><span>Automation</span><strong><?php echo (int)seom_get('indexing_enabled',0)?'ON':'OFF'; ?></strong></div></div>
<div class="seom-two"><div class="seom-panel"><h3>Manual URL submission</h3><p>Submit up to 100 URLs at a time. Use <strong>Update</strong> for a new/changed URL and <strong>Delete</strong> after the content leaves the server.</p><textarea id="seom-indexing-urls" rows="8" class="widefat" placeholder="One URL per line"></textarea><p><select id="seom-indexing-type"><option value="update">URL Updated</option><option value="delete">URL Deleted</option></select> <button type="button" class="button button-primary" id="seom-indexing-submit">Submit to Google</button></p><pre id="seom-indexing-result" class="seom-api-result"></pre></div><div class="seom-panel"><h3>Check Google notification status</h3><p>Google can report when it last received an update notification for a specific URL.</p><input id="seom-indexing-status-url" type="url" class="widefat" placeholder="https://example.com/job/abc/"><p><button type="button" class="button" id="seom-indexing-status">Get Status</button></p><pre id="seom-indexing-status-result" class="seom-api-result"></pre></div></div>
<div class="seom-panel"><div class="seom-actions"><div><h3>Submission History</h3><p>Shows recent Indexing API attempts, response code, status and retry state.</p></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="seom_indexing_clear"><?php wp_nonce_field('seom_indexing_clear'); ?><button class="button">Clear History</button></form></div><table class="widefat striped"><thead><tr><th>URL</th><th>Action</th><th>Status</th><th>Code</th><th>Message</th><th>Time</th></tr></thead><tbody><?php if(!$logs): ?><tr><td colspan="6">No indexing requests yet.</td></tr><?php else: foreach($logs as $r): ?><tr><td style="max-width:320px;overflow-wrap:anywhere"><?php echo esc_html($r['url']); ?></td><td><?php echo esc_html(strtoupper($r['action'])); ?></td><td><span class="seom-badge <?php echo $r['status']==='success'?'ok':($r['status']==='queued'?'warn':'error'); ?>"><?php echo esc_html($r['status']); ?></span></td><td><?php echo (int)$r['response_code']; ?></td><td><?php echo esc_html($r['message']); ?></td><td><?php echo esc_html($r['created_at']); ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
